const a={gongyong:{ninhaoyoushenmenengbangdaoni:"Anggota yang Terhormat, bagaimana saya bisa membantu Anda?"},ocnal:{baipishu:"White Paper",home1:"Buka Dunia Mata Uang Digital",home2:"Deposit Sekarang",home3:"Nama",home4:"Harga",home5:"Perubahan 24h",home6:"Perdagangkan",home7:"Memulai",home8:"Buat akun",home9:"Daftarkan akun untuk menikmati lebih banyak hak istimewa dan layanan",home10:"Daftar",home11:"Deposit Dana",home12:"Isi akun Anda dan mulai berinvestasi dalam cryptocurrency",home13:"Deposit kripto",home14:"Mulai berdagang",home15:"Jual, beli atau salin perdagangan, temukan lebih banyak",home16:"Jelajahi pasar",home17:"Pasar cryptocurrency sedang berkembang pesat, mencakup mata uang digital, teknologi blockchain, dan lainnya. Prospeknya menjanjikan, tetapi investasi membutuhkan kehati-hatian.",home18:"Spot",home19:"Perdagangan waktu nyata di pasar spot dengan perubahan harga yang cepat.",home20:"Kontrak abadi",home21:"Perdagangan kontrak menyediakan perdagangan dengan leverage, yang dapat mencapai keuntungan tinggi.",home22:"Opsi",home23:"Perdagangan opsi menyediakan strategi lindung nilai fleksibel untuk mengontrol risiko dan memperoleh keuntungan.",home24:"Investasi AI",home25:"Rencanakan dengan Percaya Diri. Investasikan dengan Cerdas. Kurangi Kekhawatiran",home26:"Tingkat Pengembalian Tahunan Tertinggi dalam Sejarah",home27:"Saat ini",home28:"Reguler",home29:"Beli Sekarang",home30:"Semua orang bisa menggunakan mata uang digital",home31:"Dari pengalaman awal perdagangan mata uang digital hingga pembelian pertama produk keuangan, platform akan membantu Anda dengan mudah mendapatkan koin",home32:"Pelajari tentang cryptocurrency",home33:"Pelajari semua tentang cryptocurrency untuk mulai berinvestasi",home34:"Pertanyaan yang Sering Diajukan",home35:"Siap memulai perjalanan kripto Anda?",home36:"Apa itu bursa cryptocurrency?",home37:"Bursa cryptocurrency adalah pasar digital yang memungkinkan pengguna membeli dan menjual cryptocurrency seperti Bitcoin, Ethereum, dan Tether. Bursa Binance adalah bursa kripto terbesar berdasarkan volume perdagangan.",home38:"Produk apa saja yang ditawarkan platform?",home39:"Sebagai platform perdagangan cryptocurrency global terkemuka, platform saat ini melayani lebih dari 150 juta pengguna terdaftar di lebih dari 180 negara/wilayah. Dengan biaya transaksi rendah, platform menawarkan lebih dari 350 cryptocurrency yang dapat diperdagangkan, menjadikannya pilihan utama untuk perdagangan Bitcoin, altcoin, dan aset digital lainnya. <br><br> Di platform, pengguna dapat: <br><br>1. Perdagangkan ratusan cryptocurrency dan pasangan perdagangan.<br><br>2. Beli dan jual cryptocurrency melalui perdagangan spot platform.<br><br>3. Dapatkan bunga cryptocurrency melalui manajemen kekayaan platform",home40:"Bagaimana cara memperdagangkan cryptocurrency di platform",home41:"Di platform, Anda dapat memperdagangkan ratusan cryptocurrency di pasar spot, futures, dan opsi. Untuk memulai perdagangan, pengguna perlu mendaftar akun di platform, menyelesaikan verifikasi identitas, dan deposit/beli cryptocurrency, lalu mereka dapat mulai berdagang.",home42:"Apakah platform ini bursa cryptocurrency yang aman?",home43:"Platform ini berkomitmen menyediakan platform perdagangan yang aman dan terpercaya. Kami memiliki salah satu teknologi keamanan dan tim pemeliharaan paling canggih di dunia, termasuk tim keamanan khusus yang terus bekerja untuk memastikan keamanan aset dan akun Anda. Kami juga telah menjalani verifikasi bukti cadangan independen untuk memastikan semua aset pengguna didukung dengan rasio 1:1.",home44:"Bagaimana cara mengatasi lupa kata sandi login?",home45:"Anda dapat mengklik 'Lupa Kata Sandi' di halaman login, kemudian atur ulang 'Kata Sandi Login'.",home46:"Mengapa Anda perlu Otentikasi Identitas?",home47:"Untuk keamanan dana Anda dan mencegah kegiatan pencucian uang, kami perlu memastikan akun penerima terkait dengan informasi identitas akun saat ini.",home48:"Pasar",home49:"Pasar perdagangan cryptocurrency global mendukung transaksi multi-mata uang, menawarkan keamanan dan efisiensi.",home50:"Akun Saya",home51:"Deposit",home52:"Tarik",home53:"Konversi",home54:"Populer",home55:"Investasikan di Token yang Baru Diterbitkan dan Raih Potensi Keuntungan Tinggi",home56:"Berita",home57:"Mengapa memilih kami?",home58:"Dipercaya oleh jutaan orang",home59:"Jumlah pengguna",home60:"Unit mitra",home61:"Biaya transaksi minimum",home62:"Mitra",home63:"Vol 24h",jianguanzhengshu:"Sertifikat Regulasi",falvzhengmingshu:"Sertifikat Hukum"},licai:{zhiyawakuang:"Investasi AI",zhiyawakuangjiaoyi:"Perdagangan Investasi AI",zhiya:"Investasi AI",zhiyajine:"Jumlah Investasi AI"},aurexion:{jianguanwenjian:"Dokumen Regulasi"}};export{a as default};
